// Genuinely global configuration only â detailed trend-scoring weights live
// inside "Normalize, Filter & Select Trend" itself, next to the logic that
// uses them, not duplicated here.
const jobId = $now.toFormat('yyyyLLdd-HHmmss') + '-' + Math.random().toString(36).slice(2, 8);

return [{
  json: {
    jobId,
    remotionProjectPath: '/data/crypto-video-engine-v2',
    videoJobsPath: 'public/jobs',
    outputPath: 'out/jobs',
    searchQueryUsed: 'crypto',
    freshnessHours: 12,
    minTrendScoreToWin: 25,
    dedupTtlDays: 7,
    maxTweetsPerAuthor: 3,
    maxGroqAttempts: 2,
  },
}];

// ============================================================
// CONFIG
// ============================================================
const WEIGHTS = { engagement: 1.0, velocity: 1.6, recency: 1.2, newsworthiness: 1.0, confirmation: 1.4, sourceQuality: 0.6 };
const CLUSTER_MIN_SHARED_KEYWORDS_SAME_TOKEN = 2;
const CLUSTER_MIN_SHARED_KEYWORDS_NO_TOKEN_MATCH = 3;
const RECENCY_CEILING_HOURS = 48;
const FRESHNESS_TIERS = [
  { name: 'tier1', maxHours: 12, trendLevel: 'breaking' },
  { name: 'tier2', maxHours: 24, trendLevel: 'ongoing' },
  { name: 'tier3', maxHours: 48, trendLevel: 'recent' },
];

const config = $('Job Config').first().json;

// ============================================================
// 0. Detect an upstream request failure before touching the body at all â
// a failed HTTP call (onError-style) or a non-object response must never
// silently fall through to "no candidates found -> evergreen". A broken
// fetch and "genuinely no news today" are different outcomes.
// ============================================================
const raw = $input.first().json;
if (raw && raw.error && !raw.entries && !raw.data && !raw.results && !raw.timeline && !raw.tweets) {
  return [{
    json: {
      ...config,
      contentStatus: 'source_request_failed',
      mode: null,
      totalRawResults: 0, totalTweetObjectsParsed: 0, candidateCount: 0, rejectedCount: 0,
      apiResponseShapeDetected: 'error_response', searchQueryUsed: config.searchQueryUsed || null,
    },
  }];
}

// ---- 1-4: locate + normalize every post from the raw RapidAPI response ----
function normalizeToArray(data) {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  if (typeof data === 'object') return Object.values(data);
  return [];
}
function getSafeValue(obj, paths, fallback = null) {
  for (const p of paths) {
    try {
      const value = p.split('.').reduce((acc, key) => {
        if (acc == null) return undefined;
        const arrayMatch = key.match(/^(.*)\[(\d+)\]$/);
        if (arrayMatch) {
          const arr = acc[arrayMatch[1]];
          return Array.isArray(arr) ? arr[Number(arrayMatch[2])] : undefined;
        }
        return acc[key];
      }, obj);
      if (value != null) return value;
    } catch (_) { continue; }
  }
  return fallback;
}
// Recursively scans the ENTIRE response for tweet-shaped objects,
// regardless of which top-level key they live under (entries, data,
// results, timeline, tweets, or anything else) â does not assume any
// particular root shape, per the requirement not to assume raw.entries.
function extractTweetLikeObjects(node, collected = [], visited = new WeakSet()) {
  if (node === null || typeof node !== 'object') return collected;
  if (visited.has(node)) return collected;
  visited.add(node);
  const MARKERS = ['itemContent', 'tweet_results', 'legacy', 'full_text'];
  if (Array.isArray(node)) {
    for (const item of node) extractTweetLikeObjects(item, collected, visited);
  } else {
    const keys = Object.keys(node);
    if (MARKERS.some((m) => keys.includes(m))) collected.push(node);
    for (const key of keys) extractTweetLikeObjects(node[key], collected, visited);
  }
  return collected;
}

const topLevelKeys = raw && typeof raw === 'object' ? Object.keys(raw).filter((k) => raw[k] != null) : [];
const apiResponseShapeDetected = topLevelKeys.length > 0 ? topLevelKeys.join(',') : 'empty_or_non_object_response';

const tweetNodes = [];
extractTweetLikeObjects(raw, tweetNodes);
const totalTweetObjectsParsed = tweetNodes.length;

// Best-effort count of raw items the provider actually sent, independent of
// whether our extractor could parse them, so a real "zero results" from the
// provider is distinguishable from "we parsed 0 out of many".
const totalRawResults = (() => {
  for (const key of ['entries', 'data', 'results', 'timeline', 'tweets']) {
    const val = raw && raw[key];
    if (val != null) {
      const arr = normalizeToArray(val);
      if (arr.length > 0) return arr.length;
    }
  }
  return totalTweetObjectsParsed;
})();

if (totalTweetObjectsParsed === 0) {
  return [{
    json: {
      ...config,
      contentStatus: 'source_data_error',
      mode: null,
      totalRawResults, totalTweetObjectsParsed: 0, candidateCount: 0, rejectedCount: 0,
      apiResponseShapeDetected, searchQueryUsed: config.searchQueryUsed || null,
    },
  }];
}

// ---- Coin/project name detection â not just cashtags ----
const COIN_NAME_MAP = {
  bitcoin: 'BTC',
  ethereum: 'ETH', ether: 'ETH',
  solana: 'SOL',
  ripple: 'XRP', xrp: 'XRP',
  dogecoin: 'DOGE',
  cardano: 'ADA',
  avalanche: 'AVAX',
  chainlink: 'LINK',
  polkadot: 'DOT',
  litecoin: 'LTC',
  polygon: 'MATIC',
  tron: 'TRX',
  toncoin: 'TON',
  shiba: 'SHIB', 'shiba inu': 'SHIB',
  tether: 'USDT',
  'usd coin': 'USDC',
};
function detectCoinMentions(text) {
  const found = new Set();
  const cashtagMatches = text.match(/\$[A-Za-z]{2,10}\b/g) || [];
  for (const m of cashtagMatches) found.add(m.slice(1).toUpperCase());
  const lower = text.toLowerCase();
  for (const [name, ticker] of Object.entries(COIN_NAME_MAP)) {
    const re = new RegExp(`\\b${name.replace(/\s+/g, '\\s+')}\\b`, 'i');
    if (re.test(lower)) found.add(ticker);
  }
  return [...found];
}

const posts = [];
for (const node of tweetNodes) {
  const text = getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.full_text',
    'tweet_results.result.legacy.full_text', 'legacy.full_text', 'full_text', 'text',
  ]);
  if (!text) continue;

  const sourceId = getSafeValue(node, [
    'content.itemContent.tweet_results.result.rest_id',
    'tweet_results.result.rest_id', 'rest_id', 'id_str', 'id',
  ]);
  const createdAt = getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.created_at',
    'tweet_results.result.legacy.created_at', 'legacy.created_at', 'created_at',
    'content.itemContent.tweet_results.result.legacy.createdAt', 'createdAt', 'timestamp', 'created_time',
  ]);
  const likesRaw = getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.favorite_count',
    'tweet_results.result.legacy.favorite_count', 'legacy.favorite_count', 'favorite_count', 'like_count', 'likes',
  ], null);
  const retweetsRaw = getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.retweet_count',
    'tweet_results.result.legacy.retweet_count', 'legacy.retweet_count', 'retweet_count', 'retweets',
  ], null);
  const repliesRaw = getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.reply_count',
    'tweet_results.result.legacy.reply_count', 'legacy.reply_count', 'reply_count', 'replies',
  ], null);
  const quotes = Number(getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.quote_count',
    'tweet_results.result.legacy.quote_count', 'legacy.quote_count', 'quote_count',
  ], 0)) || 0;
  const views = getSafeValue(node, [
    'content.itemContent.tweet_results.result.views.count',
    'tweet_results.result.views.count', 'views.count',
  ], null);
  const authorHandle = getSafeValue(node, [
    'content.itemContent.tweet_results.result.core.user_results.result.legacy.screen_name',
    'tweet_results.result.core.user_results.result.legacy.screen_name',
    'legacy.user.screen_name', 'user.screen_name', 'screen_name', 'author.username', 'username',
  ], 'unknown');
  const authorFollowers = getSafeValue(node, [
    'content.itemContent.tweet_results.result.core.user_results.result.legacy.followers_count',
    'tweet_results.result.core.user_results.result.legacy.followers_count', 'author.followers_count',
  ], null);
  const authorVerified = getSafeValue(node, [
    'content.itemContent.tweet_results.result.core.user_results.result.legacy.verified',
    'tweet_results.result.core.user_results.result.is_blue_verified', 'author.verified',
  ], null);
  const cashtag = getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.entities.cashtags[0].text',
    'legacy.entities.cashtags[0].text',
  ], '');
  const hashtagsRaw = getSafeValue(node, [
    'content.itemContent.tweet_results.result.legacy.entities.hashtags',
    'legacy.entities.hashtags',
  ], []);
  const hashtags = Array.isArray(hashtagsRaw) ? hashtagsRaw.map((h) => h && h.text).filter(Boolean) : [];
  const ageMinutes = createdAt ? (Date.now() - new Date(createdAt).getTime()) / 60000 : null;
  const trimmedText = String(text).trim();
  const detectedCoins = detectCoinMentions(trimmedText);

  posts.push({
    sourceId: sourceId || Buffer.from(trimmedText).toString('base64').slice(0, 20),
    sourceType: 'x',
    sourceUrl: sourceId && authorHandle !== 'unknown' ? `https://x.com/${authorHandle}/status/${sourceId}` : '',
    text: trimmedText,
    author: authorHandle,
    authorFollowers: authorFollowers != null ? Number(authorFollowers) : null,
    authorVerified: authorVerified != null ? Boolean(authorVerified) : null,
    createdAt: createdAt || null,
    ageMinutes: ageMinutes != null && !Number.isNaN(ageMinutes) ? ageMinutes : null,
    likesRaw, retweetsRaw, repliesRaw,
    likes: likesRaw != null ? Number(likesRaw) || 0 : 0,
    retweets: retweetsRaw != null ? Number(retweetsRaw) || 0 : 0,
    replies: repliesRaw != null ? Number(repliesRaw) || 0 : 0,
    quotes,
    views: views != null ? Number(views) : null,
    token: (cashtag || '').toUpperCase() || (detectedCoins[0] || ''),
    detectedCoins,
    hashtags,
    trendScore: 0,
    trendLevel: '',
    rejectionReasons: [],
  });
}

// ---- 5-6: reject spam / low-quality, using workflow static data for dedup ----
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = {};
if (!staticData.recentTopicHashes) staticData.recentTopicHashes = {};
if (!staticData.flaggedAuthors) staticData.flaggedAuthors = {};

const now = Date.now();
const DEDUP_TTL_MS = (config.dedupTtlDays || 7) * 24 * 60 * 60 * 1000;
const FLAG_TTL_MS = 6 * 60 * 60 * 1000;
for (const k of Object.keys(staticData.processedIds)) if (now - staticData.processedIds[k] > DEDUP_TTL_MS) delete staticData.processedIds[k];
for (const k of Object.keys(staticData.recentTopicHashes)) if (now - staticData.recentTopicHashes[k] > DEDUP_TTL_MS) delete staticData.recentTopicHashes[k];
for (const k of Object.keys(staticData.flaggedAuthors)) if (now - staticData.flaggedAuthors[k] > FLAG_TTL_MS) delete staticData.flaggedAuthors[k];

const RE_ENGAGEMENT_BAIT = /\b(f[\W_]*o[\W_]*l[\W_]*l[\W_]*o[\W_]*w|r[\W_]*e[\W_]*t[\W_]*w[\W_]*e[\W_]*e[\W_]*t|\brt\b|d[\W_]*m\s*(me|us|for)|drop\s*(your\s*)?(wallet|address)|sub[\W_]*scribe)\b/i;
const RE_FINANCIAL_MANIP = /\b(\d{2,5}[xÃ]|to\s+the\s+moon|going\s+moon|next\s+gem|guaranteed\s+(profit|return|gain)|can'?t\s+miss|last\s+chance|buy\s+now|get\s+in\s+(now|early)|early\s+investors?|this\s+is\s+it|secret\s+(alpha|signal|call))\b/i;
const RE_GIVEAWAY = /\b(give[\W_]*away|air[\W_]*drop|pre[\W_]*sale|lucky\s+winner|entries?\s+close|claim\s+your|limited\s+spots?|whitelist\s+open|mint\s+is\s+(live|open)|free\s+(tokens?|nft|crypto|coins?))\b/i;
const RE_SUSP_LINKS = /(bit\.ly|t\.me\/|tinyurl\.com|linktr\.ee|shorte\.st|cutt\.ly|rb\.gy|ow\.ly)(\/\S+)?/i;
const RE_BOT_COMMANDS = /\b(join\s+(our|the|my|this)\s+(group|channel|community|telegram|discord|server)|check\s+(pinned|bio|profile)|link\s+in\s+(bio|profile)|visit\s+our|click\s+below|comment\s+(done|below)|tag\s+\d+\s+friends?|share\s+(this|to)\s+(win|get))\b/i;
const RE_CONVERSATIONAL = new RegExp([
  'good\\s+(morning|evening|night|afternoon)', 'gm\\s+crypto', 'gm\\s+web3', 'gm\\s+fam', '^gm[!.\\s]*$',
  'rise\\s+and\\s+shine', 'have\\s+a\\s+(great|good|wonderful|blessed)\\s+day',
  'happy\\s+(monday|tuesday|wednesday|thursday|friday|weekend)',
  'what\\s+do\\s+you\\s+think', 'hot\\s+take[:\\s]', 'unpopular\\s+opinion', 'agree\\s+or\\s+disagree',
  'yes\\s+or\\s+no\\??', 'your\\s+thoughts\\??', 'am\\s+i\\s+(the\\s+only\\s+one|wrong|right)',
  'who\\s+else\\s+(thinks|agrees|feels)', 'drop\\s+your\\s+(handle|wallet|address|nft)', 'best\\s+opportunity',
  'follow\\s+me\\s+(for|if)', 'check\\s+out\\s+my', 'new\\s+video\\s+out', 'i\\s+just\\s+posted', 'thread\\s+below',
  'believe\\s+in\\s+yourself', 'keep\\s+going', 'stay\\s+strong', 'never\\s+give\\s+up', 'mindset\\s+is\\s+everything',
].join('|'), 'i');
// Broadened per the requested topic list: exchanges, hacks/exploits, listings/delistings,
// partnerships/launches/upgrades, whale/on-chain activity, ETFs, regulation, price action.
const RE_NEWS_SIGNAL = new RegExp([
  '\\$[A-Z]{2,6}', '\\b(all[\\-\\s]?time\\s+high|ath|all[\\-\\s]?time\\s+low|atl)\\b',
  '\\b(price|rally|crash|correction|pump|dump|surge|plunge|breakout|breakdown|volatility|dip)\\b',
  '\\b(bull|bear)\\s+(run|market|trap|flag)\\b', '\\b(support|resistance|fibonacci|rsi|macd|volume)\\b',
  '\\b(sec|cftc|fed|federal\\s+reserve|treasury|congress|senate|regulation|regulatory|lawsuit|settlement|ruling|approved?|rejected?|compliance|sanction)\\b',
  '\\b(etf|spot\\s+etf|futures\\s+etf|approval|inflow|outflow)\\b',
  '\\b(blackrock|fidelity|vanguard|jpmorgan|goldman|citadel|grayscale|coinbase|binance|kraken|okx|bybit|bitfinex|gemini|crypto\\.com|robinhood)\\b',
  '\\b(upgrade|hard\\s+fork|soft\\s+fork|mainnet|testnet|launch|deploy|audit|exploit|hack|hacked|breach|vulnerability|bug|patch|fix|drain(ed)?|stolen)\\b',
  '\\b(layer[\\s\\-]?[12]|l[12]|rollup|zk[\\s\\-]?proof|zkevm|optimism|arbitrum|polygon|lightning\\s+network)\\b',
  '\\b(smart\\s+contract|defi|dex|cex|nft|dao|staking|yield|liquidity|liquidat(ed|ion)|tvl|protocol)\\b',
  '\\b(partnership|acquisition|merger|funding|investment|venture|series\\s+[a-c]|ipo|token\\s+sale|ido|ico|listing|listed|delist(ed|ing)?)\\b',
  '\\b(bankruptcy|insolvency|collapse|insolvent|chapter\\s+11|creditor)\\b',
  '\\b(inflation|interest\\s+rate|gdp|recession|macro|cpi|unemployment)\\b',
  '\\b(wallet|custody|cold\\s+storage|hardware\\s+wallet|ledger|trezor)\\b',
  '\\b(billion|million|trillion|market\\s+cap|dominance|hash\\s+rate|on[\\-\\s]?chain|whale|flow|moves?|movement)\\b',
  '\\b(report|data|analysis|research|survey|study|according\\s+to|source|cited?|confirmed?|breaking|announc(e|ed|ement))\\b',
].join('|'), 'i');
const RE_EMOJI = /[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{27BF}]|[\u{FE00}-\u{FEFF}]|[\u{1FA00}-\u{1FA9F}]/gu;

function countEmoji(text) { const m = (text || '').match(RE_EMOJI); return m ? m.length : 0; }
function isSpam(text) {
  const lower = text.toLowerCase();
  if (RE_ENGAGEMENT_BAIT.test(lower)) return 'engagement_bait';
  if (RE_FINANCIAL_MANIP.test(lower)) return 'financial_manipulation';
  if (RE_GIVEAWAY.test(lower)) return 'giveaway_scam';
  if (RE_SUSP_LINKS.test(text)) return 'suspicious_link';
  if (RE_BOT_COMMANDS.test(lower)) return 'bot_command';
  if (countEmoji(text) > 6) return `emoji_flood_${countEmoji(text)}`;
  return null;
}

const debugLog = [];
const rejectionReasonCounts = {};
function recordRejection(post, reasons) {
  post.rejectionReasons = reasons;
  for (const r of reasons) rejectionReasonCounts[r] = (rejectionReasonCounts[r] || 0) + 1;
  debugLog.push({ sourceId: post.sourceId, text: post.text.slice(0, 70), reasons });
}

const candidates = [];
for (const post of posts) {
  const reasons = [];
  if (RE_CONVERSATIONAL.test(post.text)) reasons.push('conversational_filler');

  const spamReason = isSpam(post.text);
  if (spamReason) reasons.push(spamReason);

  // Newsworthy if the keyword regex matches OR a real coin/project was
  // detected by name (not just cashtag) â a plain-word "Bitcoin" or
  // "Solana" mention is a legitimate signal on its own.
  const hasNewsSignal = RE_NEWS_SIGNAL.test(post.text) || post.detectedCoins.length > 0;
  if (!hasNewsSignal) reasons.push('not_newsworthy');

  // Engagement: missing fields are "unknown", not "zero quality". A zero
  // total is only held against a post if it is NOT very fresh â breaking
  // news is frequently still at zero likes/retweets in its first minutes,
  // and must not be discarded for that reason alone.
  const hasEngagementData = post.likesRaw != null || post.retweetsRaw != null || post.repliesRaw != null;
  const totalEngagement = post.likes + post.retweets + post.replies;
  const ageHoursForFilter = post.ageMinutes != null ? post.ageMinutes / 60 : null;
  const isVeryFresh = ageHoursForFilter != null && ageHoursForFilter <= 2;
  if (hasEngagementData && totalEngagement <= 0 && !isVeryFresh) {
    reasons.push('zero_engagement_and_not_fresh');
  }

  const authorKey = (post.author || 'unknown').toLowerCase();
  if (staticData.flaggedAuthors[authorKey]) reasons.push('author_on_penalty_list');
  if (staticData.processedIds[post.sourceId]) reasons.push('duplicate_id');

  if (reasons.length > 0) { recordRejection(post, reasons); continue; }
  candidates.push(post);
}

const authorCounts = {};
const filteredCandidates = [];
for (const c of candidates) {
  const key = (c.author || 'unknown').toLowerCase();
  authorCounts[key] = (authorCounts[key] || 0) + 1;
  if (authorCounts[key] > (config.maxTweetsPerAuthor || 3)) {
    staticData.flaggedAuthors[key] = now;
    recordRejection(c, ['author_flood']);
    continue;
  }
  filteredCandidates.push(c);
}

// ---- 6: tiered freshness classification ----
for (const c of filteredCandidates) {
  const ageHours = c.ageMinutes != null ? c.ageMinutes / 60 : null;
  if (ageHours == null) {
    c.trendLevel = 'unusable_as_primary_missing_timestamp';
    c.freshnessTier = null;
  } else if (ageHours < -5 / 60) {
    // A few minutes of clock skew is tolerated; further in the future is not.
    c.trendLevel = 'unusable_as_primary_future_timestamp';
    c.freshnessTier = null;
  } else {
    const tier = FRESHNESS_TIERS.find((t) => ageHours <= t.maxHours);
    if (tier) { c.trendLevel = tier.trendLevel; c.freshnessTier = tier.name; }
    else { c.trendLevel = 'stale'; c.freshnessTier = null; }
  }
}

// ---- 8: cluster by event/topic similarity, not token alone ----
const STOPWORDS = new Set(['about', 'after', 'their', 'there', 'which', 'would', 'could', 'should', 'crypto', 'market', 'because', 'before', 'still', 'while', 'where', 'these', 'those', 'other', 'being']);
function extractKeywords(text) {
  const words = text.toLowerCase().match(/[a-z]{4,}/g) || [];
  return [...new Set(words.filter((w) => !STOPWORDS.has(w)))];
}
function sharedKeywordCount(a, b) {
  const setB = new Set(b);
  let shared = 0;
  for (const w of a) if (setB.has(w)) shared++;
  return shared;
}

for (const c of filteredCandidates) c.keywords = extractKeywords(c.text);

const clusters = [];
for (const c of filteredCandidates) {
  let placed = false;
  for (const cluster of clusters) {
    const rep = cluster[0];
    const sameToken = Boolean(c.token) && c.token === rep.token;
    const threshold = sameToken ? CLUSTER_MIN_SHARED_KEYWORDS_SAME_TOKEN : CLUSTER_MIN_SHARED_KEYWORDS_NO_TOKEN_MATCH;
    if (sharedKeywordCount(c.keywords, rep.keywords) >= threshold) {
      cluster.push(c);
      placed = true;
      break;
    }
  }
  if (!placed) clusters.push([c]);
}
for (const cluster of clusters) for (const c of cluster) c.clusterMembers = cluster;

// ---- 9: score (recency uses a shared 48h ceiling so tier2/tier3 posts still earn partial credit) ----
function scoreCandidate(c) {
  const ageHours = c.ageMinutes != null ? Math.max(c.ageMinutes / 60, 0.05) : null;
  const engagement = Math.log10(1 + c.likes * 1 + c.retweets * 2 + c.replies * 1.5 + (c.quotes || 0) * 1.5) * 20;
  const velocity = ageHours != null ? Math.log10(1 + (c.likes + c.retweets * 2 + c.replies) / ageHours) * 25 : 0;
  const recency = ageHours != null && ageHours >= 0 ? Math.max(0, RECENCY_CEILING_HOURS - ageHours) / RECENCY_CEILING_HOURS * 20 : 0;
  const newsworthiness = RE_NEWS_SIGNAL.test(c.text) ? 15 : (c.detectedCoins.length > 0 ? 10 : 0);
  const clusterSize = (c.clusterMembers || [c]).length;
  const confirmation = Math.min(clusterSize - 1, 4) * 8;
  const sourceQuality = (c.authorVerified ? 8 : 0) + (c.authorFollowers && c.authorFollowers > 10000 ? 5 : 0);
  // A very fresh post from a verified/established account still needs to be
  // able to win before engagement accumulates â a small, capped freshness
  // grace credit, not a substitute for the recency score itself.
  const freshnessGrace = (c.trendLevel === 'breaking' && c.authorVerified) ? 6 : 0;
  const penalties = ageHours == null ? -10 : 0;

  const breakdown = {
    engagement: Math.round(engagement * WEIGHTS.engagement),
    velocity: Math.round(velocity * WEIGHTS.velocity),
    recency: Math.round(recency * WEIGHTS.recency),
    newsworthiness: Math.round(newsworthiness * WEIGHTS.newsworthiness),
    confirmation: Math.round(confirmation * WEIGHTS.confirmation),
    sourceQuality: Math.round(sourceQuality * WEIGHTS.sourceQuality),
    freshnessGrace,
    penalties,
  };
  return { total: Object.values(breakdown).reduce((a, b) => a + b, 0), breakdown, clusterSize };
}

for (const c of filteredCandidates) {
  const { total, breakdown, clusterSize } = scoreCandidate(c);
  c.trendScore = total;
  c.scoreBreakdown = breakdown;
  c.clusterSize = clusterSize;
}
filteredCandidates.sort((a, b) => b.trendScore - a.trendScore);

// ---- 10-11: select winner tier by tier, evergreen only if nothing in any tier qualifies ----
let winner = null;
for (const tier of FRESHNESS_TIERS) {
  const tierCandidates = filteredCandidates
    .filter((c) => c.freshnessTier === tier.name)
    .sort((a, b) => b.trendScore - a.trendScore);
  const found = tierCandidates.find((c) => c.trendScore >= (config.minTrendScoreToWin || 25));
  if (found) { winner = found; break; }
}

const EVERGREEN_LIBRARY = [
    { topic: 'Bitcoin Halving Cycles', angle: 'How supply shocks historically preceded bull markets and what to watch for next.', token: 'BTC' },
    { topic: 'DeFi Yield Strategies', angle: 'A beginner-friendly breakdown of liquidity pools, staking, and risk management.', token: 'GENERAL_MARKET' },
