    { topic: 'Crypto Portfolio Diversification', angle: 'The 80/20 rule for digital assets: core holdings vs. high-risk bets.', token: 'GENERAL_MARKET' },
    { topic: 'Understanding Market Cycles', angle: 'Fear & greed index deep-dive - how sentiment drives price action.', token: 'GENERAL_MARKET' },
    { topic: 'NFT Utility Beyond JPEGs', angle: 'Real-world use cases: ticketing, IP ownership, and gaming assets.', token: 'GENERAL_MARKET' },
