    { topic: 'On-Chain Data Analysis', angle: 'How to read wallet movements and exchange flows to spot smart money.', token: 'GENERAL_MARKET' },
    { topic: 'Web3 Identity & Wallets', angle: 'Self-custody vs. exchanges: why your keys matter more than ever.', token: 'GENERAL_MARKET' },
    { topic: 'Tokenomics 101', angle: 'Supply schedules, vesting cliffs, and why they make or break a project.', token: 'GENERAL_MARKET' },
    { topic: 'Cross-Chain Bridges', angle: 'How assets move between blockchains and the security risks involved.', token: 'GENERAL_MARKET' },
    { topic: 'Ethereum Proof-of-Stake', angle: 'How the Merge changed ETH issuance, validators, and environmental impact.', token: 'ETH' },
    { topic: 'Solana vs. Ethereum', angle: 'Speed vs. decentralisation - an honest comparison for developers and traders.', token: 'SOL' },
    { topic: 'Crypto Tax Basics', angle: 'What counts as a taxable event and how to keep records without going mad.', token: 'GENERAL_MARKET' },
    { topic: 'DAO Governance Explained', angle: 'How decentralised organisations make decisions - and where they still fail.', token: 'GENERAL_MARKET' },
