    { topic: 'Bull vs. Bear Market Psychology', angle: 'Cognitive biases - FOMO, anchoring, loss aversion - and how to counter them.', token: 'GENERAL_MARKET' },
  ];

let mode, selected;
if (winner) {
  mode = 'TREND_MODE';
  selected = {
    text: winner.text,
    token: winner.token || 'GENERAL_MARKET',
    likes: winner.likes, retweets: winner.retweets, replies: winner.replies,
    score: winner.trendScore, scoreBreakdown: winner.scoreBreakdown, sourceId: winner.sourceId,
    supportingSourceIds: (winner.clusterMembers || []).filter((c) => c.sourceId !== winner.sourceId).map((c) => c.sourceId),
    clusterSize: winner.clusterSize,
  };
} else {
  mode = 'EVERGREEN_MODE';
  const usedRecently = new Set(Object.keys(staticData.recentTopicHashes));
  const available = EVERGREEN_LIBRARY.filter((t) => !usedRecently.has(t.topic));
  const pool = available.length > 0 ? available : EVERGREEN_LIBRARY;
  const topic = pool[Math.floor(Math.random() * pool.length)];
  selected = { text: topic.angle, token: topic.token, evergreenTopic: topic.topic, evergreenAngle: topic.angle, likes: 0, retweets: 0, replies: 0, score: 0 };
}

// ---- 12: rich debug output (Â§8) without breaking any field AI Agent/downstream nodes already rely on ----
const highestScore = filteredCandidates.length > 0 ? filteredCandidates[0].trendScore : null;
const debugInfo = {
  totalRawResults,
  totalTweetObjectsParsed,
  candidateCount: filteredCandidates.length,
  rejectedCount: posts.length - filteredCandidates.length,
  rejectionReasonCounts,
  highestScore,
  selectedScore: winner ? winner.trendScore : null,
  selectedText: winner ? winner.text : null,
  selectedSourceId: winner ? winner.sourceId : null,
  selectedSourceUrl: winner ? winner.sourceUrl : null,
  selectedAuthor: winner ? winner.author : null,
  selectedCreatedAt: winner ? winner.createdAt : null,
  selectedAgeHours: winner && winner.ageMinutes != null ? Math.round((winner.ageMinutes / 60) * 100) / 100 : null,
  selectedToken: winner ? winner.token : null,
  selectedMode: mode,
  scoreBreakdown: winner ? winner.scoreBreakdown : null,
  apiResponseShapeDetected,
  searchQueryUsed: config.searchQueryUsed || null,
};

return [{ json: { ...config, contentStatus: 'ok', mode, ...selected, debugLog, ...debugInfo } }];

const trend = $('Normalize, Filter & Select Trend').first().json;
const jobId = $('Job Config').first().json.jobId;

// Attempt count is derived purely from THIS execution's own graph data â
// specifically, the previous loop pass's "Script Route" output â never from
// workflow static data ($getWorkflowStaticData). Static data is a
// cross-execution DB-backed store; on a freshly imported/unsaved workflow,
// or under a plain manual execution, mutations written earlier in the very
// same run are not reliably visible to later nodes (this is the confirmed
// root cause of the "Cannot read properties of undefined" crash that used
// to happen in Prepare Job Manifest). $('Script Route') is a completely
// different mechanism â n8n's own per-execution pairedItem graph â and is
// unaffected by that persistence issue; it's the same kind of reference
// Convert Text to Speech already uses successfully to read this node's
// latest (valid) output.
function getPreviousAttempt() {
  try {
    const prev = $('Script Route').first().json;
    return prev && typeof prev.attempt === 'number' ? prev.attempt : 0;
  } catch (e) {
    return 0; // Script Route has not run yet this execution -> this is attempt 1
  }
}
const attempt = getPreviousAttempt() + 1;

function routeFail(reason) {
  const maxAttempts = trend.maxGroqAttempts || 2;
  if (attempt < maxAttempts) {
    return [{
      json: {
        route: 'retry',
        jobId,
        attempt,
        retryNote: `Your previous attempt was rejected: ${reason}. Follow the rules exactly this time â do not repeat this mistake.`,
      },
    }];
  }
  return [{ json: { route: 'failed', jobId, reason } }];
}

const raw = $json.output ?? $json.text ?? '';
if (!raw || typeof raw !== 'string') return routeFail('AI Agent returned empty output');

const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return routeFail(`JSON parse failed: ${e.message}`);
}

let script = parsed.script;
if (!script || typeof script !== 'string') return routeFail('Missing script field');
if (!parsed.disclaimer || typeof parsed.disclaimer !== 'string') return routeFail('Missing disclaimer field');

script = script.replace(/^[A-Za-z\s]{1,30}:\s*/i, '');
script = script.replace(/\(.*?\)/g, '');
script = script.replace(/\[.*?\]/g, '');
script = script.replace(/\*.*?\*/g, '');
script = script.replace(/And as always[\s\S]*?Do your own research\.?/gi, '');
script = script.replace(/\s{2,}/g, ' ').trim();

const disclaimer = 'And as always â this is for educational purposes only, not financial advice. Do your own research.';

const wordCount = script.split(/\s+/).filter(Boolean).length;
const maxWords = trend.mode === 'EVERGREEN_MODE' ? 90 : 60;
if (wordCount === 0) return routeFail('Script is empty after cleaning');
if (wordCount > maxWords) return routeFail(`Script exceeds ${maxWords}-word limit (${wordCount} words)`);

const BANNED_PHRASES = [
  'in the world of crypto', "it's important to note", "let's dive in", "let's break this down",
  'in recent years', 'in recent news', 'many investors believe', 'experts say',
  'as we know', 'exciting times', 'revolutionary', 'game-changing', 'disruptive', 'so basically',
];
const lowerScript = script.toLowerCase();
const foundBanned = BANNED_PHRASES.find((p) => lowerScript.includes(p));
if (foundBanned) return routeFail(`Contains banned phrase: "${foundBanned}"`);

// Valid â downstream nodes (Convert Text to Speech, Prepare Job Manifest,
// Prepare Manual Upload Package) all read the script/disclaimer straight
// off $('Parse & Validate Script').first() themselves, via n8n's own
// per-execution reference mechanism. Nothing needs to be stashed in
// workflow static data for this execution to see it.
return [{ json: { route: 'valid', jobId, script, disclaimer, wordCount, attempt } }];

