const jobConfig = $('Job Config').first().json;

// Read the validated script/disclaimer directly off Parse & Validate
// Script's own output â a normal n8n cross-node reference, resolved via
// this execution's pairedItem graph, exactly like Convert Text to Speech
// already does. This node only ever runs on the Script Route "valid" path
// (valid -> Convert Text to Speech -> Save Audio File -> here), so it
// always resolves to the SAME (latest, valid) run of Parse & Validate
// Script that produced the script actually sent to ElevenLabs â never a
// stale rejected attempt from an earlier Groq retry pass.
//
// This replaces a previous design that stashed the validated script in
// workflow static data ($getWorkflowStaticData) keyed by jobId. That
// mechanism is a cross-execution, DB-backed store; on a freshly imported
// or unsaved workflow (and under plain manual executions generally),
// writes made earlier in the very same run are not reliably visible to
// later nodes, which was the exact cause of a "Cannot read properties of
// undefined" crash here. Static data is still used elsewhere in this
// workflow, but only for genuinely cross-execution history (dedup /
// recently-used-topics), never as a same-run transport like this was.
const validated = $('Parse & Validate Script').first().json;
if (!validated || typeof validated.script !== 'string' || typeof validated.disclaimer !== 'string') {
  throw new Error(`Prepare Job Manifest: could not resolve a validated script/disclaimer for job ${jobConfig.jobId} from Parse & Validate Script's output.`);
}

const manifest = {
  jobId: jobConfig.jobId,
  script: validated.script,
  disclaimer: validated.disclaimer,
  audioRelPath: `jobs/${jobConfig.jobId}/narration.mp3`,
};

return [{ json: { ...jobConfig, ...manifest } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = {};
if (!staticData.recentTopicHashes) staticData.recentTopicHashes = {};

let trend = {};
try { trend = $('Normalize, Filter & Select Trend').first().json; } catch (e) { /* not reached, e.g. LOCKED before fetch never happens now â kept defensive */ }
const jobId = trend.jobId || $json.jobId;

let final;
if ($json.route === 'failed') {
  // Came straight from Script Route â no render was ever attempted, so
  // ElevenLabs/render credits were never spent on this attempt.
  final = { status: 'SCRIPT_VALIDATION_FAILED', jobId, error: $json.reason };
} else if ($json && typeof $json.status === 'string') {
  // Came from Render Video (HTTP Request to the render-server helper) â
  // the response body is already the parsed JSON status object
  // (VIDEO_READY / RENDER_FAILED / LOCKED / AUDIO_MISSING / etc.), not a
  // raw stdout line, since HTTP Request auto-parses the JSON response.
  final = $json;
  final.jobId = final.jobId || jobId;
} else {
  // Defensive fallback for the old Execute Command shape, kept in case
  // Render Video is ever pointed back at a shell command instead of HTTP.
  const stdout = $json.stdout || '';
  const lines = stdout.trim().split('\n').filter(Boolean);
  const lastLine = lines[lines.length - 1] || '{}';
  try {
    final = JSON.parse(lastLine);
  } catch (e) {
    final = { status: 'RENDER_FAILED', error: `Could not parse helper output: ${lastLine}` };
  }
  final.jobId = final.jobId || jobId;
}

const now = Date.now();
if (final.status === 'VIDEO_READY') {
  if (trend.sourceId) staticData.processedIds[trend.sourceId] = now;
  for (const sid of (trend.supportingSourceIds || [])) staticData.processedIds[sid] = now;
  const topicKey = trend.evergreenTopic || trend.token || (trend.text || '').slice(0, 40);
  if (topicKey) staticData.recentTopicHashes[topicKey] = now;
  staticData.lastSuccessfulRun = new Date(now).toISOString();
  staticData.lastJob = { jobId, outputPath: final.outputPath, completedAt: staticData.lastSuccessfulRun };
  final.mode = trend.mode || null;
  final.sourceId = trend.sourceId || null;
}
staticData.lastRunStatus = { jobId, status: final.status, at: new Date(now).toISOString() };

const clean = {
  status: final.status,
  jobId,
  outputPath: final.outputPath || null,
  durationInSeconds: final.durationInSeconds || null,
  width: final.width || null,
  height: final.height || null,
  fps: final.fps || null,
  mode: final.mode || null,
  sourceId: final.sourceId || null,
  error: final.error || null,
};

return [{ json: clean }];

// Gate: only continue when the render genuinely succeeded and the MP4
// exists. Returning an empty array halts this branch with no items â the
// standard n8n way to stop a Code node's output without an extra IF node.
if ($json.status !== 'VIDEO_READY' || $json.error) {
  return [];
}

const jobId = $json.jobId;
const jobConfig = $('Job Config').first().json;

// The rendered MP4's container-visible path â reconstructed from Job
// Config's own dynamic fields (never a hardcoded filename), matching the
// bind-mounted VPS path already used by every other node in this workflow.
const videoPath = `${jobConfig.remotionProjectPath}/${jobConfig.outputPath}/${jobId}.mp4`;

// Finalize Result intentionally strips script/topic text from its own
// output, so pull that from where it was actually produced:
//  - trend/topic data from "Normalize, Filter & Select Trend" (runs
//    exactly once per job, outside the Groq retry loop â always safe).
//  - the actual narrated script from "Parse & Validate Script", read
//    defensively (try/catch): this node can run more than once if Groq
//    needed a retry, and this text is only going into a human-reviewed
//    text file (not another automated action), so a rare stale read here
//    is low-stakes and self-correcting on review â unlike an unattended
//    API call, which is why this project avoids this same reference
//    elsewhere.
const trend = $('Normalize, Filter & Select Trend').first().json;
let scriptText = '';
try {
  scriptText = $('Parse & Validate Script').first().json.script || '';
} catch (e) {
  scriptText = '';
}

function cleanText(text) {
  return String(text || '').replace(/[\r\n]+/g, ' ').replace(/\s{2,}/g, ' ').trim();
}
function truncate(text, max) {
  if (text.length <= max) return text;
  return text.slice(0, max - 1).trim() + 'â¦';
}

const isEvergreen = trend.mode === 'EVERGREEN_MODE';
const CLICKBAIT_RE = /\b(guaranteed profits?|guaranteed returns?|buy now|sell now|100x|1000x|get rich(\s+quick)?|easy money|risk[- ]free|this coin will explode)\b/gi;
function stripClickbait(text) {
  return String(text || '').replace(CLICKBAIT_RE, '').replace(/\s{2,}/g, ' ').trim();
}
// Applied once here, up front, so every downstream use (title AND
// description) is already clean â a banned phrase must never leak through
// via either field.
const hookSource = stripClickbait(cleanText(scriptText) || cleanText(isEvergreen ? trend.evergreenAngle : trend.text));

// ---- coin/topic label, reused for title, hashtags, and tags ----
const TICKER_TO_NAME = {
  BTC: 'Bitcoin', ETH: 'Ethereum', SOL: 'Solana', XRP: 'XRP', DOGE: 'Dogecoin',
  ADA: 'Cardano', AVAX: 'Avalanche', LINK: 'Chainlink', DOT: 'Polkadot',
  LTC: 'Litecoin', MATIC: 'Polygon', TRX: 'Tron', TON: 'Toncoin', SHIB: 'Shiba Inu',
  USDT: 'Tether', USDC: 'USD Coin',
};
const rawToken = isEvergreen ? (trend.token || '') : (trend.token || '');
const hasRealCoin = rawToken && rawToken !== 'GENERAL_MARKET';
const coinName = hasRealCoin ? (TICKER_TO_NAME[rawToken] || rawToken) : '';
const topicLabel = isEvergreen
  ? (trend.evergreenTopic || 'Crypto Market Update')
  : (hasRealCoin ? coinName : 'Crypto Market');

// ---- topic category detection, for hashtags/tags only (no invented facts) ----
const CATEGORY_PATTERNS = {
  Regulation: /\b(sec|regulation|regulatory|lawsuit|congress|senate|compliance|ruling|approv(al|ed)|reject(ed|ion))\b/i,
  Hack: /\b(hack(ed)?|exploit(ed)?|breach|drain(ed)?|stolen|vulnerability)\b/i,
  ETF: /\b(etf|spot\s+etf|futures\s+etf)\b/i,
  DeFi: /\b(defi|liquidity|yield|staking|protocol|dex)\b/i,
  Exchange: /\b(coinbase|binance|kraken|okx|bybit|exchange)\b/i,
};
let category = null;
for (const [name, re] of Object.entries(CATEGORY_PATTERNS)) {
  if (re.test(hookSource)) { category = name; break; }
}

// ---- TITLE ----
const SHORTS_SUFFIX = ' #Shorts';
let titleBase = topicLabel && hookSource
  ? `${topicLabel}: ${truncate(hookSource, 60)}`
  : truncate(hookSource, 80) || topicLabel || 'Crypto Market Update';
titleBase = stripClickbait(titleBase).replace(/\s+:/g, ':').trim();
const maxBase = 100 - SHORTS_SUFFIX.length;
if (titleBase.length > maxBase) titleBase = truncate(titleBase, maxBase - 1);
const title = (titleBase + SHORTS_SUFFIX).trim();

// ---- HASHTAGS (3-5, dynamic from the real topic) ----
const hashtagList = [];
if (hasRealCoin) hashtagList.push(`#${coinName.replace(/\s+/g, '')}`);
if (category) hashtagList.push(`#Crypto${category}`.replace('#CryptoExchange', '#CryptoNews').replace('#CryptoDeFi', '#DeFi'));
hashtagList.push('#CryptoNews');
if (hashtagList.length < 3) hashtagList.push('#CryptoMarket');
hashtagList.push('#Shorts');
const hashtags = [...new Set(hashtagList)].slice(0, 5);

// ---- TAGS (5-10, comma list) ----
const tagList = ['crypto', 'cryptocurrency', 'crypto news'];
if (hasRealCoin) {
  tagList.push(coinName.toLowerCase());
  tagList.push(rawToken.toLowerCase());
}
if (category) tagList.push(category.toLowerCase());
tagList.push(isEvergreen ? 'crypto education' : 'crypto market update');
const tags = [...new Set(tagList)].slice(0, 10);

// ---- DESCRIPTION ----
// Built primarily from the already Groq-validated script text itself (not
// re-synthesized), so nothing here can invent a fact, price, or claim that
// wasn't already vetted earlier in the workflow.
const EXACT_DISCLAIMER = 'This content is for educational and informational purposes only and does not constitute financial advice. Always do your own research.';
const sourceLine = (!isEvergreen && trend.sourceUrl) ? `\nSource: ${trend.sourceUrl}` : '';
const description = [
  truncate(hookSource, 1000),
  '',
  hashtags.join(' '),
  sourceLine.trim(),
  '',
  EXACT_DISCLAIMER,
].filter((line) => line !== '').join('\n');

// ---- upload settings block (fixed text, not generated) ----
const uploadSettingsBlock = [
  'Visibility: Public',
  'Audience: Not made for kids',
  'Language: English',
  'Title and description language: English',
  'Category: Education',
  'License: Standard YouTube License',
  'Thumbnail: Select the opening hook frame',
].join('\n');

const sourceInfoLine = !isEvergreen
  ? `Live trend â token: ${trend.token || 'GENERAL_MARKET'}${trend.sourceUrl ? `, source: ${trend.sourceUrl}` : ''}${trend.author ? `, author: @${trend.author}` : ''}`
  : `Evergreen educational topic: ${trend.evergreenTopic || topicLabel}`;

const fileContent = `==================================================
CRYPTO FRAMES â MANUAL YOUTUBE UPLOAD PACKAGE
==================================================

JOB ID
${jobId}

TITLE
${title}

DESCRIPTION
${description}

HASHTAGS
${hashtags.join(' ')}

TAGS
${tags.join(',')}

UPLOAD SETTINGS
${uploadSettingsBlock}

VIDEO FILE
${videoPath}

SOURCE/TOPIC
${sourceInfoLine}
`;

const uploadDetailsFileName = `${jobId}-upload-details.txt`;
const binary = await this.helpers.prepareBinaryData(Buffer.from(fileContent, "utf8"), uploadDetailsFileName, "text/plain");

return [{
  json: {
    jobId,
    videoPath,
    outputPath: jobConfig.outputPath,
    remotionProjectPath: jobConfig.remotionProjectPath,
    title,
    description,
    hashtags,
    tags,
    uploadDetailsFileName,
    uploadDetailsContent: fileContent,
  },
  binary: { data: binary },
}];
